insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('teacher-audio','teacher-audio',false,15728640,array['audio/webm','audio/mp4','audio/mpeg','audio/ogg']) on conflict(id) do nothing;insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('student-audio','student-audio',false,15728640,array['audio/webm','audio/mp4','audio/mpeg','audio/ogg']) on conflict(id) do nothing;
create policy "teacher audio owned quiz" on storage.objects for all to authenticated using(bucket_id='teacher-audio' and exists(select 1 from public.quizzes q where q.id::text=split_part(name,'/',1) and q.teacher_id=auth.uid())) with check(bucket_id='teacher-audio' and exists(select 1 from public.quizzes q where q.id::text=split_part(name,'/',1) and q.teacher_id=auth.uid()));
create policy "student audio own folder" on storage.objects for all to authenticated using(bucket_id='student-audio' and split_part(name,'/',1)=auth.uid()::text) with check(bucket_id='student-audio' and split_part(name,'/',1)=auth.uid()::text);
create policy "teachers read student audio" on storage.objects for select to authenticated using(bucket_id='student-audio' and exists(select 1 from public.student_answers a join public.submissions s on s.id=a.submission_id join public.quizzes q on q.id=s.quiz_id where a.audio_path=name and q.teacher_id=auth.uid()));
